import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Index","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/index-drives.md","filePath":"user-guide/settings/index-drives.md","lastUpdated":1783655657000}'),s={name:"user-guide/settings/index-drives.md"};function n(i,e,l,d,u,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h1><p>Four tabs: <strong>Local Drives</strong>, <strong>Network Drives</strong>, <strong>Folders</strong>, and <strong>Exclusion Rules</strong>.</p><h2 id="local-drives" tabindex="-1">Local Drives <a class="header-anchor" href="#local-drives" aria-label="Permalink to &quot;Local Drives&quot;">​</a></h2><ul><li>Status card summarizing how many drives and items are indexed, plus a <strong>Rebuild Index</strong> button for a full re-scan.</li><li>One row per local drive: an <strong>enable/disable checkbox</strong>, drive name, file system (NTFS/ReFS/...), current status, indexed item count, and a per-row <strong>Rebuild</strong>/<strong>Remove</strong> action.</li><li>Local drives update continuously from the Windows USN Journal — a manual rebuild is rarely needed, but is there if something looks out of sync.</li></ul><h2 id="network-drives" tabindex="-1">Network Drives <a class="header-anchor" href="#network-drives" aria-label="Permalink to &quot;Network Drives&quot;">​</a></h2><ul><li>Same status card and <strong>Rebuild Index</strong> button as Local Drives.</li><li>One row per mapped network drive: enable checkbox, path/name, status (Indexing / Ready / Cached / Failed / Pending / Connected), item count, and a <strong>Refresh Mode</strong> dropdown: <ul><li><strong>Manual</strong> — only refreshes on demand (via Rebuild Index).</li><li><strong>Every 15 minutes</strong></li><li><strong>Every hour</strong></li><li><strong>Daily</strong></li></ul></li><li>A <strong>WSL Distributions</strong> sub-section appears automatically if you have Windows Subsystem for Linux installed, listing each distribution with the same enable/status/refresh-mode controls as a network drive.</li></ul><p>Network shares don&#39;t expose a change journal the way local NTFS volumes do, which is why they&#39;re refreshed on a schedule instead of in real time.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><p>Index arbitrary individual folders instead of a whole drive or share — useful for indexing just one subtree without pulling in everything else on that volume.</p><ul><li>An <strong>Add Folder</strong> button opens a folder picker; a <strong>Rebuild Index</strong> button re-scans every folder in the list.</li><li>One row per added folder: enable checkbox, path, status, item count, and the same <strong>Refresh Mode</strong> dropdown (Manual / Every 15 minutes / Every hour / Daily) as network drives — folders are scanned on a schedule rather than tracked continuously, the same way network shares are.</li></ul><h2 id="exclusion-rules" tabindex="-1">Exclusion Rules <a class="header-anchor" href="#exclusion-rules" aria-label="Permalink to &quot;Exclusion Rules&quot;">​</a></h2><p>Three sub-tabs, each with the same shape: a single-entry textbox + <strong>Add</strong> button, a list of existing rules (each editable/deletable), and a bulk multi-line textbox with <strong>Generate from List</strong> / <strong>Apply to List</strong> buttons for editing everything at once.</p><ul><li><strong>Path Exclusions</strong> — full paths or environment variables (e.g. <code>D:\\Cache</code>, <code>%ProgramData%</code>).</li><li><strong>Glob Wildcards</strong> — <code>*</code> (any characters in a filename), <code>?</code> (single character), <code>**</code> (recursive directories). Examples: <code>*.tmp</code>, <code>**/node_modules/**</code>, <code>bin/**</code>.</li><li><strong>Regex Patterns</strong> — arbitrary regular expressions matched against the path/filename (partial match). Examples: <code>^\\.</code> (hidden files), <code>~$</code> (Office temp files), <code>\\.git\\</code>.</li></ul><p>Exclusions apply to local, network, and folder indexing alike, and network drives/folders re-scan automatically after you apply exclusion changes.</p>',14)])])}const m=r(s,[["render",n]]);export{g as __pageData,m as default};
